import {stats,CLASSES} from './core.js?v=25';
import {KITS} from './skills.js?v=25';
import {appearanceFor} from './loadout.js?v=25';
import {skillArt} from './skill-art.js?v=25';
import {commandIcon} from './ui-design.js?v=25';
import {ensureSociety,vipState,VIP_TIERS,buyVip,inviteBot,botReply,simulateDays,cohortReport,simulateBotDay,tickFollowers} from './bot-society.js?v=25';
import {createMatch,arenaAction,arenaMove,tickMatch} from './bot-arena.js?v=25';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=n=>Math.round(n||0).toLocaleString('pt-BR'),label=p=>({free:'FREE',vip:'VIP',patron:'ALTO INVESTIMENTO'}[p]);
export function createSocialUI({getPlayer,state,renderer,showModal,closeModal,save,feed,blocked,onStrike}){
 let selected='bot-0',match=null,scenario=null,busy=false,clock=0,walkClock=0,simClock=0,botCursor=0,arenaStamp=0,move=0;const $=id=>document.getElementById(id),world=()=>ensureSociety(getPlayer());
 const nav=tab=>`<nav class="socialTabs">${[['people','JOGADORES IA'],['arena','ARENA'],['scenario','SIMULAÇÕES'],['vip','PACTOS VIP']].map(([id,name])=>`<button data-social="${id}" class="${id===tab?'selected':''}">${name}</button>`).join('')}</nav>`;
 function open(tab='people'){match=null;move=0;const p=getPlayer(),w=world();let content='';
 if(tab==='people')content=`<div class="societyBanner"><div>${commandIcon('ranking')}<span><small>SERVIDOR SIMULADO · IA LOCAL</small><h3>50 histórias. Um mundo em movimento.</h3><p>30 free · 12 VIP · 8 de alto investimento. Converse, forme grupo e teste builds.</p></span></div><b>${w.party.length+1}/5 <small>NO GRUPO</small></b></div><div class="socialFilters"><input id="botSearch" aria-label="Buscar bot" placeholder="Buscar nome ou classe"><select id="botFilter" aria-label="Perfil do bot"><option value="all">Todos os perfis</option><option value="free">Free</option><option value="vip">VIP</option><option value="patron">Alto investimento</option></select><button id="partyDismiss">DESFAZER GRUPO</button></div><div id="citizenGrid" class="citizenGrid"></div>`;
 else if(tab==='arena')content=`<div class="societyBanner"><div>${commandIcon('skills')}<span><small>COMBATE JOGÁVEL CONTRA IA</small><h3>O equipamento é só o começo.</h3><p>Mova, ataque e execute habilidades. Ou assista a dois bots com decisões próprias.</p></span></div></div><div class="arenaSetup"><label>Adversário<select id="arenaOpponent">${w.bots.map(b=>`<option value="${b.id}" ${b.id===selected?'selected':''}>${b.name} · ${CLASSES[b.classId].name} · ${label(b.profile)}</option>`).join('')}</select></label><label>Regras<select id="arenaRules"><option value="equal">Equalizada · mesmo orçamento de atributos</option><option value="free">Livre · equipamentos atuais</option></select></label><button id="arenaEnter" class="primary">LUTAR CONTRA IA →</button><button id="arenaWatch">ASSISTIR BOT × BOT</button></div><div class="socialMetrics"><div><small>SUAS VITÓRIAS CONTRA BOTS</small><b>${w.arena.wins}</b></div><div><small>DERROTAS</small><b>${w.arena.losses}</b></div><div><small>EMPATES</small><b>${w.arena.draws}</b></div></div><p class="socialNote">Liga local separada do PvP humano. Sem prêmio por farmar bots. Partidas duram até 90s; sair abandona o combate sem vitória. A conta GM mantém sua build; a arena usa HP próprio.</p>`;
 else if(tab==='vip'){const vip=vipState(p);content=`<div class="societyBanner"><div>${commandIcon('shop')}<span><small>SEU PACTO · ${vip.name.toUpperCase()}</small><h3>Privilégios claros. Compras de teste.</h3><p>Bônus de ouro e materiais comuns de caça: +${Math.round(vip.bonus*100)}%. Sem bônus direto de dano.</p></span></div></div><div class="vipCards">${VIP_TIERS.slice(1).map(v=>`<article><small>VIP ${v.level}</small><h3>${v.name}</h3><b>+${v.bonus*100}%</b><p>Ouro e Fragmentos de Magícula de monstros comuns.<br>Identificação VIP no HUD.</p><button data-vip="${v.level}" ${vip.level>=v.level?'disabled':''}>${vip.level>=v.level?'ATIVO / INCLUÍDO':num(Math.max(0,v.threshold-(p.vip.spent||0)))+' CASH · ATIVAR'}</button></article>`).join('')}</div><p class="socialNote">Pagamento único simulado para cada patamar, sem assinatura. O valor pago no pacto anterior abate o seguinte. Não aumenta drop raro de chefes, força na arena, títulos de conquista ou taxa de encantamento.</p>`;}
 else content=`<div class="societyBanner"><div>${commandIcon('attributes')}<span><small>LABORATÓRIO · 50 PERFIS PERSISTENTES</small><h3>Compare tempo, gasto e crescimento.</h3><p>Free: 2h/dia, sem cash. VIP: 3h e 10.000 cash/dia. Alto investimento: 4h e 100.000 cash/dia.</p></span></div></div><div class="scenarioActions">${[1,7,30].map(d=>`<button data-sim-days="${d}" ${busy?'disabled':''}>SIMULAR ${d} DIA${d>1?'S':''}</button>`).join('')}<b id="scenarioProgress">${busy?'SIMULAÇÃO EM ANDAMENTO':'DIA GLOBAL '+w.days}</b></div><div id="scenarioReport">${report()}</div><p class="socialNote">Dias virtuais, sem alterar o calendário, seu nível ou seus recursos. Usa EXP, cotação de treinamento e encantamento do jogo. Modelo agregado de caça; não simula sessões completas nem comprova equilíbrio ou comportamento de jogadores reais. Perfis começam com equipamentos diferentes. A comparação mistura tempo, investimento e build inicial.</p>`;
 showModal('Mundo & Arena','ALPHA 0.25 · 50 JOGADORES SIMULADOS',nav(tab)+content);$('modal').querySelector('.modal').dataset.panel='social';document.querySelectorAll('[data-social]').forEach(b=>b.onclick=()=>open(b.dataset.social));
 if(tab==='people'){drawCitizens();$('botSearch').oninput=drawCitizens;$('botFilter').onchange=drawCitizens;$('partyDismiss').onclick=()=>{w.party=[];save();open();};}
 if(tab==='arena'){$('arenaEnter').onclick=()=>launch($('arenaOpponent').value,false,$('arenaRules').value==='equal');$('arenaWatch').onclick=()=>launch($('arenaOpponent').value,true,$('arenaRules').value==='equal');}
 if(tab==='vip')document.querySelectorAll('[data-vip]').forEach(b=>b.onclick=()=>{const tier=VIP_TIERS.find(t=>t.level===Number(b.dataset.vip)),price=Math.max(0,tier.threshold-(p.vip.spent||0));showModal('Ativar '+tier.name,'CONFIRMAÇÃO · CASH SIMULADO',`<p>${num(price)} cash de teste. Saldo: ${num(p.wallet.cash)}.</p><p>+${tier.bonus*100}% de ouro e Fragmentos de Magícula em monstros comuns. Não modifica dano ou recompensas raras.</p><button id="vipConfirm" class="primary">CONFIRMAR PACTO</button><button id="vipCancel">VOLTAR</button>`);$('vipConfirm').onclick=()=>{const result=buyVip(p,tier.level);if(!result.ok){$('modalSub').textContent=result.reason;return;}save();open('vip');};$('vipCancel').onclick=()=>open('vip');});
 if(tab==='scenario')document.querySelectorAll('[data-sim-days]').forEach(b=>b.onclick=async()=>{if(busy)return;busy=true;document.querySelectorAll('[data-sim-days]').forEach(b=>b.disabled=true);try{scenario=await simulateDays(w,Number(b.dataset.simDays),(d,total)=>{if($('scenarioProgress'))$('scenarioProgress').textContent='DIA '+d+' / '+total;});for(const b of w.bots){delete b.cachedStats;delete b.appearance;}save();if($('scenarioReport'))$('scenarioReport').innerHTML=report();}finally{busy=false;document.querySelectorAll('[data-sim-days]').forEach(b=>b.disabled=false);}});
 }
 function report(){const w=world(),rows=scenario?.after||cohortReport(w);return `<div class="scenarioTable"><div><b>PERFIL</b><b>NV MÉDIO</b><b>PODER MÉDIO</b><b>CASH USADO</b></div>${rows.map(r=>{const prev=scenario?.before.find(x=>x.profile===r.profile);return `<div><strong>${label(r.profile)} <small>${r.count} bots</small></strong><span>${r.level}${prev?' <small>Δ '+(r.level-prev.level)+'</small>':''}</span><span>${num(r.power)}${prev?' <small>Δ '+num(r.power-prev.power)+'</small>':''}</span><span>${num(r.spent)}</span></div>`;}).join('')}</div>${scenario?'<p class="socialNote">Última simulação: '+scenario.days+' dias. Saldo não gasto permanece com cada bot. Cash usado é treinamento comprado, não todo o orçamento recebido.</p>':''}`;}
 function drawCitizens(){const text=$('botSearch').value.toLowerCase(),filter=$('botFilter').value,w=world();$('citizenGrid').innerHTML=w.bots.filter(b=>(filter==='all'||b.profile===filter)&&(b.name+' '+CLASSES[b.classId].name).toLowerCase().includes(text)).map(b=>`<button class="citizenCard ${w.party.includes(b.id)?'inParty':''}" data-bot="${b.id}"><span class="botPortrait botPortrait${b.classId}">${commandIcon(b.classId==='ARC'?'aura':b.classId==='VIG'?'skills':'forge')}</span><span><b>${b.name} <em>IA</em></b><small>${CLASSES[b.classId].name} · Nv ${b.player.level} · ${label(b.profile)}</small><strong>${num((b.cachedStats||stats(b.player)).pc)} PODER</strong><small>${w.party.includes(b.id)?'NO SEU GRUPO · SEGUINDO':b.intent}</small></span></button>`).join('');document.querySelectorAll('[data-bot]').forEach(b=>b.onclick=()=>profile(b.dataset.bot));}
 function profile(id){match=null;selected=id;const w=world(),b=w.bots.find(x=>x.id===id);if(!b)return;const st=b.cachedStats=stats(b.player);showModal(b.name+' · IA',CLASSES[b.classId].name.toUpperCase()+' · '+label(b.profile)+' · NV '+b.player.level,`<div class="botProfile"><canvas id="botPortraitCanvas" width="220" height="230" aria-label="Personagem ${b.name}"></canvas><section><small>PERSONALIDADE · ${b.personality.toUpperCase()}</small><h3>${b.intent}</h3><div class="socialMetrics"><div><small>PODER</small><b>${num(st.pc)}</b></div><div><small>VITÓRIAS IA</small><b>${b.wins}</b></div><div><small>DIAS SIMULADOS</small><b>${b.days}</b></div></div><p>ATK ${num(st.atk)} · HP ${num(st.hp)} · Crítico ${Math.round(st.crit*100)}% · Dano crítico ${Math.round((st.critd-1)*100)}%</p><div class="botActions"><button id="botInvite" class="primary">${w.party.includes(id)?'REMOVER DO GRUPO':'CONVIDAR PARA GRUPO'}</button><button id="botDuel">DESAFIAR NA ARENA</button><button id="botObserve">OBSERVAR NO MUNDO</button></div></section></div><div class="botChatLog" id="botChatLog" role="log">${w.messages.filter(m=>m.bot===id).slice(-8).map(m=>`<p><b>${esc(m.author)}:</b> ${esc(m.text)}</p>`).join('')||'<p>Este é um bot com IA local por regras. Pergunte sobre grupo, equipamento, VIP, história ou arena.</p>'}</div><form id="botChatForm" class="botChatForm"><input aria-label="Mensagem para o bot" id="botChatInput" maxlength="180" placeholder="Fale com ${b.name}…"><button>ENVIAR</button></form><p class="socialNote" id="botActionNote">Você pode conversar também pelo chat do HUD usando @${b.name}.</p>`);$('modal').querySelector('.modal').dataset.panel='social';renderer.portrait($('botPortraitCanvas'),b.classId,appearanceFor(b.player));$('botInvite').onclick=()=>{const out=inviteBot(w,id);if(!out.ok){$('botActionNote').textContent=out.reason;return;}b.region=getPlayer().region||0;b.zone=getPlayer().zone;b.x=getPlayer().x+2;b.y=getPlayer().y+1;save();profile(id);};$('botDuel').onclick=()=>launch(id,false,true);$('botObserve').onclick=()=>{const p=getPlayer();b.region=p.region||0;b.zone=p.zone;b.x=p.x+3;b.y=p.y+1;closeModal();};$('botChatForm').onsubmit=e=>{e.preventDefault();const text=$('botChatInput').value.trim();if(!text)return;talk(id,text);$('botChatInput').value='';$('botChatLog').innerHTML=w.messages.filter(m=>m.bot===id).slice(-8).map(m=>`<p><b>${esc(m.author)}:</b> ${esc(m.text)}</p>`).join('');$('botChatLog').scrollTop=$('botChatLog').scrollHeight;};$('botChatInput').onkeydown=e=>e.stopPropagation();}
 function talk(id,message){const w=world(),b=w.bots.find(b=>b.id===id)||w.bots[0],response=botReply(b,message,w);selected=b.id;w.messages.push({bot:b.id,author:getPlayer().name,text:message.slice(0,180)},{bot:b.id,author:b.name+' [IA]',text:response});w.messages=w.messages.slice(-100);feed.speak(b.name+' [IA]',response);save();return response;}
 feed.setResponder(message=>{const w=world(),named=w.bots.find(b=>message.toLowerCase().includes('@'+b.name.toLowerCase()));talk(named?.id||selected,message);});
 function launch(id,watch,equalized){selected=id;const w=world(),b=w.bots.find(b=>b.id===id),other=w.bots[(w.bots.indexOf(b)+1)%50],p=getPlayer(),a=watch?{name:other.name+' [IA]',classId:other.classId,level:other.player.level,stats:stats(other.player),botId:other.id}:{name:p.name,classId:p.classId,level:p.level,stats:stats(p)},opponent={name:b.name+' [IA]',classId:b.classId,level:b.player.level,stats:stats(b.player),botId:b.id};match=createMatch(a,opponent,{seed:Date.now(),watch,equalized});if(equalized)match.fighters.forEach(f=>f.level=1000);showModal('Arena dos Ecos',`${watch?'ESPECTADOR':'JOGADOR × IA'} · ${equalized?'EQUALIZADA':'BUILD LIVRE'} · ATÉ 90s`,`<div class="liveArenaHeader"><span id="arenaLife0"></span><b id="arenaClock">0:00</b><span id="arenaLife1"></span></div><canvas id="liveArenaCanvas" width="720" height="160" aria-label="Duelo em tempo real"></canvas><div class="arenaDock">${watch?'<span>Os dois bots decidem movimento, ataque e habilidades.</span>':`<button id="arenaLeft" aria-label="Mover à esquerda">◀</button><button id="arenaRight" aria-label="Mover à direita">▶</button><button id="arenaBasic">ATACAR</button>${KITS[p.classId].map((k,i)=>`<button data-arena-skill="${i}" aria-label="${k.name}">${skillArt(k,p.classId,i===6)}<small>${i+1}</small></button>`).join('')}`}</div><div id="arenaEvents" class="arenaEvents" role="log"></div><div id="arenaResult" class="arenaResult" aria-live="polite"></div><button id="arenaBack">VOLTAR À ARENA</button>`);$('modal').querySelector('.modal').dataset.panel='liveArena';$('arenaBack').onclick=()=>open('arena');if(!watch){$('arenaBasic').onclick=()=>{match.autoBasic=!match.autoBasic;$('arenaBasic').classList.toggle('selected',match.autoBasic);};document.querySelectorAll('[data-arena-skill]').forEach(b=>b.onclick=()=>{const index=Number(b.dataset.arenaSkill);if(!arenaAction(match,0,index)&&!match.done&&match.fighters[0].cd[index]<=0)match.queued={index,until:match.time+1.8};});for(const [id,dir] of [['arenaLeft',-1],['arenaRight',1]]){const el=$(id);el.onpointerdown=e=>{e.preventDefault();el.setPointerCapture(e.pointerId);move=dir;};el.onpointerup=el.onpointercancel=()=>move=0;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')arenaMove(match,0,dir,.08);};}}arenaStamp=0;}
 function drawArena(dt){const m=match,canvas=$('liveArenaCanvas');if(!m||!canvas||$('modal').hidden){match=null;move=0;return;}if(!m.watch&&move)arenaMove(m,0,move,dt);tickMatch(m,dt);const g=canvas.getContext('2d'),t=m.time;g.clearRect(0,0,720,160);const bg=g.createLinearGradient(0,0,0,160);bg.addColorStop(0,'#091726');bg.addColorStop(1,'#19303d');g.fillStyle=bg;g.fillRect(0,0,720,160);g.strokeStyle='#7aafbd44';for(let i=0;i<7;i++){g.beginPath();g.ellipse(360,137,40+i*48,10+i*6,0,0,Math.PI*2);g.stroke();}for(let n=0;n<2;n++){const f=m.fighters[n],x=55+f.x*37;g.save();g.translate(x,127);g.scale(.65,.65);const prev=renderer.g;renderer.g=g;renderer.human(f.classId,f.lock<=0&&Math.abs(f.x-m.fighters[1-n].x)>f.st.range,t,f.attackAnim>0,{quality:'SSS',weaponQuality:'SSS',hasWeapon:true,hasArmor:true,hasSecondary:f.classId!=='RUP',enchant:50,attackProgress:1-f.attackAnim/.5,facingLeft:n===1});renderer.g=prev;g.restore();g.font='11px system-ui';g.textAlign='center';g.fillStyle=n?'#ffb9be':'#a3e7ff';g.fillText(f.name,x,150);}
 for(const e of m.events.slice(-5)){if(t-e.time>.6||!e.damage)continue;const target=m.fighters[1-e.n],x=55+target.x*37;g.fillStyle=e.critical?'#ffe2a0':'#d7f1ff';g.font=e.critical?'bold 16px system-ui':'12px system-ui';g.fillText(num(e.damage),x,65-(t-e.time)*35);g.strokeStyle=e.n?'#b997ff':'#70e6ff';g.lineWidth=3;g.beginPath();g.moveTo(55+m.fighters[e.n].x*37,101);g.lineTo(x,97);g.stroke();}
 arenaStamp+=dt;if(arenaStamp>.12){arenaStamp=0;m.fighters.forEach((f,i)=>{$('arenaLife'+i).innerHTML=`<b>${esc(f.name)}</b><small>${num(f.hp)} / ${num(f.st.hp)} HP · MP ${num(f.mp)}</small><i><u style="width:${f.hp/f.st.hp*100}%"></u></i>`;});$('arenaClock').textContent=Math.floor(t)+'s';$('arenaEvents').textContent=m.events.slice(-2).map(e=>m.fighters[e.n].name+': '+e.label+(e.damage?' · '+num(e.damage):'')).join(' | ');document.querySelectorAll('[data-arena-skill]').forEach(b=>{const i=Number(b.dataset.arenaSkill),cd=m.fighters[0].cd[i];b.disabled=cd>0||m.done;b.querySelector('small').textContent=cd>0?Math.ceil(cd)+'s':i+1;});}
 if(m.done&&!m.recorded){m.recorded=true;const w=world();if(m.winner!==null){const winner=m.fighters[m.winner],loser=m.fighters[1-m.winner];if(winner.botId)w.bots.find(b=>b.id===winner.botId).wins++;if(loser.botId)w.bots.find(b=>b.id===loser.botId).losses++;}if(!m.watch){if(m.winner===0)w.arena.wins++;else if(m.winner===1)w.arena.losses++;else w.arena.draws++;}save();$('arenaResult').textContent=m.winner===null?'EMPATE · LIMITE DE TEMPO':m.fighters[m.winner].name+' VENCEU · '+t.toFixed(1)+'s';}}
 function tick(dt){if(!getPlayer())return;const w=world(),p=getPlayer();if(match)drawArena(dt);if(!$('modal').hidden)return;clock+=dt;walkClock+=dt;simClock+=dt;if(simClock>=12&&!busy){simClock=0;const b=w.bots[botCursor++%50];simulateBotDay(b);delete b.cachedStats;delete b.appearance;}w.combatTarget=state.target&&((state.attack||state.time-state.lastCombat<3))?state.target:null;state.bots=tickFollowers(w,p,state.enemies,dt,blocked,onStrike);const party=new Set(w.party);for(const b of w.bots){if(party.has(b.id))continue;if(b.region!==(p.region||0)||p.zone!=='coast')continue;const angle=clock*.12+Number(b.id.slice(4))*1.7,nx=b.x+Math.cos(angle)*dt*.5,ny=b.y+Math.sin(angle)*dt*.5;b.moving=true;if(!blocked(nx,ny,'coast')){b.x=nx;b.y=ny;}state.bots.push(b);}state.bots=state.bots.slice(0,50);if(walkClock>45){walkClock=0;const b=w.bots[Math.floor(clock/45)%50];feed.speak(b.name+' [IA]',b.intent+'. Se precisar de grupo, abra Mundo & Arena.');}}
 return{open,profile,tick,start(){const w=world();state.bots=w.bots;feed.speak('Mundo [IA]','50 bots ativos. Abra Mundo & Arena para conversar, formar grupo e duelar.');},get world(){return world();}};
}
